import{z as n,x as p,o as r,c as d,q as s,j as i,D as t,d as E,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"ATT&CK","description":"","frontmatter":{"title":"ATT&CK","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mitre-attack.md","filePath":"cs/mitre-attack.md","lastUpdated":1791063341000}'),T={name:"cs/mitre-attack.md"};function m(C,a,B,c,h,u){const l=p("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="att-ck" tabindex="-1">ATT&amp;CK <a class="header-anchor" href="#att-ck" aria-label="Permalink to &quot;ATT&amp;CK&quot;">​</a></h1><div class="epigraph"><p>ATT&amp;CK 把对手行为收成战术与技术矩阵，便于问检测覆盖而不是只问 CVE 列表。它是共同语言，不是自动等于你已被打穿。</p><footer>—— MITRE ATT&amp;CK；Strom 等对知识库的陈述</footer></div><p>上一课<a href="/cs/incident-response">事件响应</a>要求把对手行为定性成有名字的事件，名字从哪来？缺口是<strong>对手行为词典</strong>。本课讲矩阵怎么用于覆盖缺口，不把技术条目写成操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工单写「中了某家族恶意软件」，换个家族检测就全对不上——产品名易变，行为才稳定。ATT&amp;CK 把行为收成两层：战术是「对手要达成什么」（初始访问、执行、持久化、横移、外送等），战术下挂技术与子技术，是「具体怎么做」。有了词典才能做映射：把自家遥测逐条对到技术上，回答「哪些技术我们根本看不见」——比如没有进程命令行日志，相关执行类技术全是盲区。缺口是映射遥测，不是数条目。</p><p><span class="marginnote">直觉类比：战术像体检项目（心血管、呼吸……），技术像具体症状（某一种心律、某一处阴影）。医生不会把所有可能的病全查一遍，而是按你的年龄与暴露史选项目——对应「按威胁模型圈定战术，再补盲区」。</span></p><h3 id="不是清单作业" tabindex="-1">不是清单作业 <a class="header-anchor" href="#不是清单作业" aria-label="Permalink to &quot;不是清单作业&quot;">​</a></h3><p>覆盖 100% 技术既不可能也无意义：矩阵条目数以百计，全盯等于没盯。按威胁模型选子集——你所在行业最常见的对手惯用哪几条战术，就先补哪里。</p><p><span class="marginnote">MITRE。禁止按矩阵当攻击剧本。渗透测试下一课是授权下的检验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>次序是先圈后对：按威胁模型圈定相关战术，再逐战术对照日志源——端点、身份、网络流——给每项技术标注「有遥测 / 有检测 / 全盲」，全盲项按可达性排序补齐。覆盖表要随 ATT&amp;CK 年度修订与遥测变化更新，不是一次性的。下一课渗透测试方法论。</p><p><span class="marginnote">术语翻译：「遥测」就是安全传感器采集到的原始记录——进程命令行、登录日志、DNS 查询。日志源没开，对应技术的格子只能填「全盲」：不是检测规则写得差，是根本没有输入可看。</span></p>',13)),(r(),i(A,null,{default:t(()=>[o(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAC%5B%22%E6%88%98%E6%9C%AF%22%5D%20--%3E%20TECH%5B%22%E6%8A%80%E6%9C%AF%22%5D%0A%20%20TECH%20--%3E%20TEL%5B%22%E9%81%A5%E6%B5%8B%E6%9C%89%E6%97%A0%22%5D%0A%20%20TEL%20--%3E%20GAP%5B%22%E6%A3%80%E6%B5%8B%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"共同语言让蓝队与情报对接：威胁情报报告用同一套技术 ID 描述对手，蓝队可把报告直接翻译成覆盖表更新；红队与检测团队也能对着矩阵约定「这次验证某项技术」。缺口表由此成为可执行合同而不是年度汇报。渗透测试下一课用授权模拟来检验这些缺口是否真被看见。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易把 ATT&CK 当成又一个 CVE 漏洞库。实际上它不登记漏洞编号，只描述「对手做了什么动作」——同一个技术（如命令行执行）可以借十个不同漏洞实现，检测针对的是动作而非漏洞。")],-1)),(r(),i(A,null,{default:t(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20INTEL%5B%22%E5%A8%81%E8%83%81%E6%83%85%E6%8A%A5%E6%8A%A5%E5%91%8A%22%5D%20--%3E%7C%22%E6%8A%80%E6%9C%AF%20ID%22%7C%20BLUE%5B%22%E8%93%9D%E9%98%9F%22%5D%0A%20%20BLUE%20--%3E%20COV%5B%22%E8%A6%86%E7%9B%96%E8%A1%A8%E6%9B%B4%E6%96%B0%22%5D%0A%20%20RED%5B%22%E7%BA%A2%E9%98%9F%2F%E6%A3%80%E6%B5%8B%E5%9B%A2%E9%98%9F%22%5D%20--%3E%7C%22%E7%BA%A6%E5%AE%9A%E9%AA%8C%E8%AF%81%E6%9F%90%E9%A1%B9%E6%8A%80%E6%9C%AF%22%7C%20TEST%5B%22%E6%8E%88%E6%9D%83%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20TEST%20--%3E%20COV%0A%20%20COV%20--%3E%20GAPS%5B%22%E7%BC%BA%E5%8F%A3%3D%E5%8F%AF%E6%89%A7%E8%A1%8C%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不展开技术利用——矩阵是描述层，不是工具手册。渗透测试方法论下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>响应需要分类语言；ATT&amp;CK 给行为词典。</li><li>用来找检测缺口，不是打勾游戏。</li><li>按威胁模型选子集。</li><li>下一课渗透测试方法论。</li><li>出处：MITRE ATT&amp;CK。</li></ul>',4))])}const D=n(T,[["render",m]]);export{_ as __pageData,D as default};
